------------ lifeCycle ------------

function HomelandCheckInPopupDialog:CleanProperties()
    self.comp = nil
    self.type = nil
    self.groupDataList = nil
    self.cellName = nil
end

function HomelandCheckInPopupDialog:InitComponent()
    SetButtonAction(self.BtnClose1.gameObject, function()
        UIModule.BackDialog()
    end)
    if self.type == 1 then
        -- 总览
        self.cellName = "HLEntryOverviewPopupCell"
    elseif self.type == 2 then
        -- 选择队伍
        self.cellName = "HLSelectTeamPopupCell"
    end
end

function HomelandCheckInPopupDialog:RefreshTitle()
    KTool.SetActive(self.TxtSubTitle, self.type == 2)
    if self.type == 1 then
        -- 总览
        CfUtils.FillText(self.TxtTitle, localize("录入总览"))
    elseif self.type == 2 then
        -- 选择队伍
        CfUtils.FillText(self.TxtTitle, localize("选择录入"))
        CfUtils.FillText(self.TxtSubTitle, localize("选择队伍"))
    end
end

function HomelandCheckInPopupDialog:RefreshGroupList()
    local allVo = self.comp:GetAllGroupVo()
    self.groupDataList = {}
    for i, vo in ipairs(allVo) do
        local groupId = vo.groupId
        -- 只显示未解锁的小队
        if not self.comp:IsGroupUnlocked(groupId) then
            table.insert(self.groupDataList, vo)
        end
    end
    -- 把没有卡牌的小组放下面
    self:DownNoHasCardGroup(self.groupDataList)
    self:RefreshLoopListView(#self.groupDataList)
end

function HomelandCheckInPopupDialog:RefreshLoopListView(maxNum)
    if not self.LoopListView.IsListViewInit then
        self.LoopListView:InitListView(maxNum, Bind(self, self.OnGetItemByIndex))
        self.LoopListView:UpdateDisplayItemCount(self.cellName)
    else
        GameUtils.ReloadData(self.LoopListView, maxNum)
    end
end

function HomelandCheckInPopupDialog:OnGetItemByIndex(loopListView, index)
    if index < 0 then
        return nil
    end
    local luaIndex = index + 1

    local cell = loopListView:NewListViewItem(self.cellName)
    local animRoot = cell.transform:Find("AnimRoot")
    if isNotNull(animRoot) then
        CfUtils.PlayAnimator(animRoot, "Go")
    end

    local LB_cell = GetLuaBehaviour(cell.gameObject, PopupCellLuaPath)
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        LB_cell:Init()
        KTool.SetActive(cell, true)
    end
    local LT_cell = LB_cell.Env
    local cellData = self.groupDataList[luaIndex]
    LT_cell:Refresh(cellData, self.type)

    return cell
end

--- 把没有卡牌的小组放下面
---@param groupList any
function HomelandCheckInPopupDialog:DownNoHasCardGroup(groupList)
    table.inPlaceBubbleSort(self.groupDataList, function(a, b)
        local hasCardA = self.comp:GetHasCardNum(a.groupId) > 0 and 1 or 0
        local hasCardB = self.comp:GetHasCardNum(b.groupId) > 0 and 1 or 0
        return hasCardA >= hasCardB
    end)
end

return HomelandCheckInPopupDialog
